-- Baseline schema for notification-service.
--
-- Generated by scripts/gen-migration-baseline.sh from the schema the previous
-- GORM AutoMigrate path produced. Every statement converges the database onto
-- that schema — tables, columns, indexes and constraints are each created only
-- if absent — so this migration creates the schema on a fresh database and
-- brings an existing one (production) up to it without a stamping step.
--
-- The per-column ALTERs matter: CREATE TABLE IF NOT EXISTS is idempotent per
-- TABLE, so on a database whose table predates a column the models added later
-- it would do nothing, and a CREATE INDEX on that column would then fail.
-- Columns added to an existing (possibly populated) table are nullable unless
-- they carry a DEFAULT; a fresh database gets the stricter CREATE TABLE form.
--
-- Do not edit by hand: change the models and regenerate, or add a NEW numbered
-- migration for schema changes from here on.

-- +goose Up
CREATE TABLE IF NOT EXISTS public.notifications (
    id uuid NOT NULL,
    user_id uuid NOT NULL,
    type text NOT NULL,
    title text NOT NULL,
    body text,
    link text,
    source_job_id uuid,
    read_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP
);

ALTER TABLE public.notifications ADD COLUMN IF NOT EXISTS id uuid;
ALTER TABLE public.notifications ADD COLUMN IF NOT EXISTS user_id uuid;
ALTER TABLE public.notifications ADD COLUMN IF NOT EXISTS type text;
ALTER TABLE public.notifications ADD COLUMN IF NOT EXISTS title text;
ALTER TABLE public.notifications ADD COLUMN IF NOT EXISTS body text;
ALTER TABLE public.notifications ADD COLUMN IF NOT EXISTS link text;
ALTER TABLE public.notifications ADD COLUMN IF NOT EXISTS source_job_id uuid;
ALTER TABLE public.notifications ADD COLUMN IF NOT EXISTS read_at timestamp with time zone;
ALTER TABLE public.notifications ADD COLUMN IF NOT EXISTS created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP;

-- +goose StatementBegin
DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint
                   WHERE conname = 'notifications_pkey'
                     AND conrelid = 'public.notifications'::regclass) THEN
        ALTER TABLE ONLY public.notifications
            ADD CONSTRAINT notifications_pkey PRIMARY KEY (id);
    END IF;
EXCEPTION WHEN duplicate_object OR duplicate_table OR invalid_table_definition THEN NULL;
END $$;
-- +goose StatementEnd

CREATE INDEX IF NOT EXISTS idx_notif_user_created ON public.notifications USING btree (user_id, created_at DESC);

CREATE UNIQUE INDEX IF NOT EXISTS idx_notif_user_source ON public.notifications USING btree (user_id, source_job_id) WHERE (source_job_id IS NOT NULL);

CREATE INDEX IF NOT EXISTS idx_notif_user_unread ON public.notifications USING btree (user_id) WHERE (read_at IS NULL);

